args <- commandArgs(trailingOnly = TRUE)
obj <- readRDS(args[[1]])
out <- args[[2]]
# R string concat: use paste0
lines <- c(paste0("root_class\t", paste(class(obj), collapse=",")))
for (nm in names(attributes(obj))) {
  a <- attr(obj, nm, exact=TRUE)
  lines <- c(lines, paste0("attr\t", nm, "\t", paste(class(a), collapse=","), "\t", length(a)))
  if (is.atomic(a) && length(a) <= 20) {
    lines <- c(lines, paste0("attr_value\t", nm, "\t", paste(head(as.character(a),20), collapse=",")))
  }
  if (is.list(a) && length(a) <= 5) {
    for (i in seq_along(a)) {
      b <- a[[i]]
      lines <- c(lines, paste0("attr_list\t", nm, "[", i, "]\t", paste(class(b), collapse=","), "\t", length(b), "\t", paste(head(as.character(b),10), collapse=",")))
    }
  }
}
writeLines(lines, out)

